"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"line\",\"x\":7.1,\"y\":5.4,\"x2\":12.1,\"y2\":5.4,\"color\":\"E3CFAE\",\"width\":1.5},{\"type\":\"text\",\"x\":7.1,\"y\":5.55,\"w\":5.0,\"h\":0.6,\"text\":\"My answer: ________   Gap: ____ units\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.9,\"y\":6.7,\"w\":11.53,\"h\":0.45,\"text\":\"The answer is revealed on the next slide.\",\"size\":14,\"color\":\"7A6650\",\"align\":\"center\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.9,\"y\":0.4,\"w\":11.53,\"h\":0.4,\"text\":\"ANSWER & COMMON MISTAKES\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"text\",\"x\":0.9,\"y\":0.75,\"w\":11.53,\"h\":0.8,\"text\":\"Practice Answer, Then Three Traps\",\"size\":34,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.9,\"y\":1.95,\"w\":11.53,\"h\":1.25,\"fill\":\"7A8450\",\"radius\":true},{\"type\":\"text\",\"x\":1.2,\"y\":2.25,\"w\":3.4,\"h\":0.65,\"text\":\"Answer: WAIT\",\"size\":28,\"color\":\"FFFFFF\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":4.7,\"y\":2.08,\"w\":7.5,\"h\":1.0,\"text\":\"109 units > 97 units. The position is 109 − 97 = 12 units above the trigger, so no order today.\",\"size\":16,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.9,\"y\":3.5,\"w\":3.6,\"h\":3.4,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":1.15,\"y\":3.65,\"w\":3.1,\"h\":0.35,\"text\":\"MISTAKE 1\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.0,\"w\":3.1,\"h\":0.85,\"text\":\"Comparing on-hand alone with the trigger\",\"size\":17,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.95,\"w\":3.1,\"h\":1.8,\"text\":\"Instead, use inventory position: on-hand + on-order − committed. In the example that is 92 units, not 89.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":4.865,\"y\":3.5,\"w\":3.6,\"h\":3.4,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":5.115,\"y\":3.65,\"w\":3.1,\"h\":0.35,\"text\":\"MISTAKE 2\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":5.115,\"y\":4.0,\"w\":3.1,\"h\":0.85,\"text\":\"Multiplying safety stock by lead time\",\"size\":17,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":5.115,\"y\":4.95,\"w\":3.1,\"h\":1.8,\"text\":\"Only daily demand is multiplied by lead time. Add safety stock once: 15 × 5 + 22 = 97 units.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":8.83,\"y\":3.5,\"w\":3.6,\"h\":3.4,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":9.08,\"y\":3.65,\"w\":3.1,\"h\":0.35,\"text\":\"MISTAKE 3\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":9.08,\"y\":4.0,\"w\":3.1,\"h\":0.85,\"text\":\"Ordering the reorder point amount\",\"size\":17,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":9.08,\"y\":4.95,\"w\":3.1,\"h\":1.8,\"text\":\"97 units is a trigger, not the order quantity. Order target − position: 197 − 92 = 105 units.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.9,\"y\":0.4,\"w\":11.53,\"h\":0.4,\"text\":\"CHECKLIST\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"text\",\"x\":0.9,\"y\":0.75,\"w\":11.53,\"h\":0.8,\"text\":\"Before You Place an Order\",\"size\":34,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.9,\"y\":1.95,\"w\":2.74,\"h\":1.95,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":1.05,\"y\":2.05,\"w\":2.45,\"h\":0.45,\"text\":\"1. Verify units\",\"size\":16,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":1.05,\"y\":2.55,\"w\":2.45,\"h\":1.25,\"text\":\"Counts and demand in units; lead time in days.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":3.83,\"y\":1.95,\"w\":2.74,\"h\":1.95,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":3.98,\"y\":2.05,\"w\":2.45,\"h\":0.45,\"text\":\"2. Include orders\",\"size\":16,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":3.98,\"y\":2.55,\"w\":2.45,\"h\":1.25,\"text\":\"Add on-order stock that is already on its way.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.76,\"y\":1.95,\"w\":2.74,\"h\":1.95,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":6.91,\"y\":2.05,\"w\":2.45,\"h\":0.45,\"text\":\"3. Subtract commitments\",\"size\":16,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":6.91,\"y\":2.55,\"w\":2.45,\"h\":1.25,\"text\":\"Remove units already promised to customers or jobs.\",\"size\":14,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":9.69,\"y\":1.95,\"w\":2.74,\"h\":1.95,\"fill\":\"C45B3A\",\"radius\":true},{\"type\":\"text\",\"x\":9.84,\"y\":2.05,\"w\":2.45,\"h\":0.45,\"text\":\"4. Check the trigger\",\"size\":16,\"color\":\"FFFFFF\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":9.84,\"y\":2.55,\"w\":2.45,\"h\":1.25,\"text\":\"Position ≤ reorder point → ORDER; otherwise WAIT.\",\"size\":14,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.9,\"y\":4.2,\"w\":3.6,\"h\":0.45,\"text\":\"Where does the position fall? (units)\",\"size\":13,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"rect\",\"x\":1.0,\"y\":4.95,\"w\":4.8,\"h\":0.65,\"fill\":\"F2D5C8\"},{\"type\":\"text\",\"x\":1.1,\"y\":5.02,\"w\":3.2,\"h\":0.5,\"text\":\"ORDER zone (≤ 97)\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":6.2,\"y\":5.02,\"w\":5.5,\"h\":0.5,\"text\":\"WAIT zone (> 97)\",\"size\":13,\"color\":\"7A8450\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":1.0,\"y\":5.6,\"x2\":12.3,\"y2\":5.6,\"color\":\"4A3B2A\",\"width\":2.5},{\"type\":\"text\",\"x\":0.45,\"y\":5.4,\"w\":0.5,\"h\":0.4,\"text\":\"80\",\"size\":12,\"color\":\"7A6650\",\"align\":\"right\"},{\"type\":\"text\",\"x\":12.35,\"y\":5.4,\"w\":0.6,\"h\":0.4,\"text\":\"120\",\"size\":12,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"line\",\"x\":5.8,\"y\":4.75,\"x2\":5.8,\"y2\":5.95,\"color\":\"4A3B2A\",\"width\":3},{\"type\":\"text\",\"x\":4.7,\"y\":4.3,\"w\":2.2,\"h\":0.45,\"text\":\"Reorder point 97\",\"size\":13,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":4.39,\"y\":5.6,\"x2\":4.39,\"y2\":6.1,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"text\",\"x\":3.29,\"y\":6.12,\"w\":2.2,\"h\":0.75,\"text\":\"92 · example\\n→ ORDER\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":9.19,\"y\":5.6,\"x2\":9.19,\"y2\":6.1,\"color\":\"7A8450\",\"width\":2.5},{\"type\":\"text\",\"x\":8.09,\"y\":6.12,\"w\":2.2,\"h\":0.75,\"text\":\"109 · practice\\n→ WAIT\",\"size\":13,\"color\":\"7A8450\",\"bold\":true,\"align\":\"center\"}]}]}","ttft_ms":85927,"type":"result","duration_ms":159009,"uuid":"5294c323-ac56-486d-89bf-41034ebb19ea","ttft_stream_ms":936,"time_to_request_ms":60,"first_content_frame_ms":937,"queued_turn_count":0,"result_index":0}

