t\",\"x\":7.75,\"y\":3.85,\"w\":4.8,\"h\":0.8,\"text\":\"Every arithmetic step shown, with units labeled.\",\"size\":15,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.9,\"y\":4.9,\"w\":0.6,\"h\":0.6,\"fill\":\"C45B3A\"},{\"type\":\"text\",\"x\":6.9,\"y\":4.95,\"w\":0.6,\"h\":0.5,\"text\":\"3\",\"size\":20,\"bold\":true,\"color\":\"FFFFFF\",\"align\":\"center\"},{\"type\":\"text\",\"x\":7.75,\"y\":4.85,\"w\":4.8,\"h\":0.45,\"text\":\"Try a practice exercise\",\"size\":19,\"bold\":true,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":7.75,\"y\":5.3,\"w\":4.8,\"h\":0.8,\"text\":\"Decide ORDER or WAIT; the answer is revealed on the following slide.\",\"size\":15,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"line\",\"x\":0.8,\"y\":6.7,\"x2\":12.53,\"y2\":6.7,\"color\":\"D9C3A0\",\"width\":1},{\"type\":\"text\",\"x\":0.8,\"y\":6.78,\"w\":11.73,\"h\":0.4,\"text\":\"All figures in this guide are synthetic training data.\",\"size\":11,\"color\":\"7A6650\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"The Rule in Three Parts\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":\"Two numbers to calculate, one comparison to make\",\"size\":15,\"align\":\"center\",\"color\":\"7A6650\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.8,\"y\":1.95,\"w\":11.73,\"h\":1.35,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"rect\",\"x\":0.8,\"y\":1.95,\"w\":0.12,\"h\":1.35,\"fill\":\"C45B3A\"},{\"type\":\"text\",\"x\":1.2,\"y\":2.05,\"w\":11.0,\"h\":0.4,\"text\":\"1 · REORDER POINT (the trigger)\",\"size\":14,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":2.45,\"w\":11.0,\"h\":0.5,\"text\":\"Reorder point = daily demand × lead time in days + safety stock\",\"size\":22,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":2.9,\"w\":11.0,\"h\":0.35,\"text\":\"Units: (units/day × days) = units, then add safety stock in units.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.8,\"y\":3.5,\"w\":11.73,\"h\":1.35,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"rect\",\"x\":0.8,\"y\":3.5,\"w\":0.12,\"h\":1.35,\"fill\":\"C45B3A\"},{\"type\":\"text\",\"x\":1.2,\"y\":3.6,\"w\":11.0,\"h\":0.4,\"text\":\"2 · INVENTORY POSITION (what you really have)\",\"size\":14,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":4.0,\"w\":11.0,\"h\":0.5,\"text\":\"Inventory position = on-hand + on-order − committed\",\"size\":22,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":4.45,\"w\":11.0,\"h\":0.35,\"text\":\"Count stock on the shelf, add stock already ordered, subtract stock already promised.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.8,\"y\":5.05,\"w\":11.73,\"h\":1.35,\"fill\":\"C45B3A\",\"radius\":true},{\"type\":\"text\",\"x\":1.2,\"y\":5.15,\"w\":11.0,\"h\":0.4,\"text\":\"3 · THE DECISION\",\"size\":14,\"bold\":true,\"color\":\"FFE9DC\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":5.55,\"w\":11.0,\"h\":0.6,\"text\":\"If inventory position ≤ reorder point → place an ORDER. Otherwise → WAIT.\",\"size\":22,\"bold\":true,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.8,\"y\":6.6,\"w\":11.73,\"h\":0.45,\"text\":\"Always compare the inventory position, not on-hand alone, with the reorder point.\",\"size\":14,\"color\":\"7A6650\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"Worked Example: Finding the Reorder Point\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":