.7,\"y\":3.95,\"w\":5.6,\"h\":0.55,\"text\":\"75 units + 22 units = 97 units\",\"size\":22,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.4,\"y\":4.85,\"w\":6.13,\"h\":1.35,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"text\",\"x\":6.7,\"y\":4.95,\"w\":5.6,\"h\":0.4,\"text\":\"STEP 3 · Read the trigger\",\"size\":14,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":6.7,\"y\":5.4,\"w\":5.6,\"h\":0.7,\"text\":\"Order when inventory position ≤ 97 units\",\"size\":20,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.8,\"y\":6.5,\"w\":11.73,\"h\":0.45,\"text\":\"Units check: units/day × days = units, so every term is in units before you add them.\",\"size\":14,\"color\":\"7A6650\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"Checking Inventory: Order or Wait?\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":\"Inventory position 92 is below the reorder point of 97, so we ORDER 105 units\",\"size\":15,\"align\":\"center\",\"color\":\"7A6650\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.8,\"y\":1.95,\"w\":5.9,\"h\":1.35,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"text\",\"x\":1.1,\"y\":2.05,\"w\":5.4,\"h\":0.4,\"text\":\"STEP 1 · Inventory position\",\"size\":14,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.1,\"y\":2.45,\"w\":5.4,\"h\":0.8,\"text\":\"89 on-hand + 20 on-order − 17 committed = 92 units\",\"size\":18,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.8,\"y\":3.45,\"w\":5.9,\"h\":1.35,\"fill\":\"C45B3A\",\"radius\":true},{\"type\":\"text\",\"x\":1.1,\"y\":3.55,\"w\":5.4,\"h\":0.4,\"text\":\"STEP 2 · Compare with the reorder point\",\"size\":14,\"bold\":true,\"color\":\"F