xt\",\"x\":7.0,\"y\":5.75,\"w\":5.75,\"h\":1.3,\"text\":\"Payback = investment ÷ annual saving; three-year net = 3 × saving − investment. Only C's reference uptime meets the 99.6% gate threshold; reference uptime is not proof of operational performance.\",\"size\":12,\"color\":\"333333\",\"align\":\"left\"}]},{\"background\":\"F5F5F5\",\"elements\":[{\"type\":\"header\",\"title\":\"PERFORMANCE: 270 UNITS BELOW SIX-MONTH TARGET\",\"subtitle\":\"Monthly output M1–M6 versus a flat target of 1,100 units per month\"},{\"type\":\"text\",\"x\":0.55,\"y\":1.72,\"w\":8.3,\"h\":0.4,\"text\":\"Monthly output vs target (units)\",\"size\":14,\"bold\":true,\"color\":\"333333\",\"align\":\"left\"},{\"type\":\"chart\",\"x\":0.55,\"y\":2.15,\"w\":8.3,\"h\":4.35,\"kind\":\"column\",\"categories\":[\"M1\",\"M2\",\"M3\",\"M4\",\"M5\",\"M6\"],\"series\":[{\"name\":\"Actual output\",\"values\":[860,790,1190,1190,1130,1170]},{\"name\":\"Target\",\"values\":[1100,1100,1100,1100,1100,1100]}],\"colors\":[\"0055A4\",\"B8C2CC\"],\"size\":11,\"legend\":true,\"labels\":true},{\"type\":\"kpi\",\"x\":9.3,\"y\":2.15,\"w\":3.45,\"h\":1.2,\"value\":\"6,330\",\"label\":\"Actual total (units)\",\"color\":\"0055A4\"},{\"type\":\"kpi\",\"x\":9.3,\"y\":3.6,\"w\":3.45,\"h\":1.2,\"value\":\"6,600\",\"label\":\"Target total (units)\",\"color\":\"8A97A6\"},{\"type\":\"kpi\",\"x\":9.3,\"y\":5.05,\"w\":3.45,\"h\":1.2,\"value\":\"−270\",\"label\":\"Shortfall (units, −4.1%)\",\"color\":\"333333\"},{\"type\":\"text\",\"x\":0.55,\"y\":6.62,\"w\":12.2,\"h\":0.6,\"text\":\"Variance vs target: M1 −240, M2 −310, M3 +90, M4 +90, M5 +30, M6 +70. Early deficit of 550 is offset by 280 surplus → net −270.\",\"size\":12,\"color\":\"333333\",\"align\":\"left\"}]},{\"background\":\"F5F5F5\",\"elements\":[{\"type\":\"header\",\"title\":\"SCENARIO: PAYBACK RANGES FROM 2.5 TO 3.8 YEARS\",\"subtitle\":\"Option B, investment fixed at $343k; saving at 80% / 100% / 120% of $113k per year\"},{\"type\":\"text\",\"x\":0.55,\"y\":1.72,\"