,\"x\":0.7,\"y\":4.65,\"w\":5.55,\"h\":0.55,\"text\":\"18 units/day × 6 days = 108 units\",\"size\":21,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.85,\"y\":4,\"w\":5.95,\"h\":1.45,\"fill\":\"E6E6E6\"},{\"type\":\"text\",\"x\":7.05,\"y\":4.15,\"w\":5.55,\"h\":0.3,\"text\":\"STEP 2 • ADD SAFETY STOCK ONCE\",\"size\":14,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":7.05,\"y\":4.65,\"w\":5.55,\"h\":0.55,\"text\":\"108 units + 26 units = 134 units\",\"size\":21,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.5,\"y\":5.8,\"w\":12.3,\"h\":0.5,\"text\":\"Interpretation: initiate a reorder when inventory position reaches 134 units or less.\",\"size\":22,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.5,\"y\":6.45,\"w\":12.3,\"h\":0.35,\"text\":\"The days cancel in Step 1. Both quantities added in Step 2 are measured in units.\",\"size\":17,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":7,\"x2\":12.8,\"y2\":7,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":7.1,\"w\":11.3,\"h\":0.2,\"text\":\"All data are synthetic. Reorder point = 18 × 6 + 26 = 134 units.\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"text\",\"x\":12.1,\"y\":7.1,\"w\":0.7,\"h\":0.2,\"text\":\"3 / 8\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"right\"}]},{\"background\":\"FFFFFF\",\"elements\":[{\"type\":\"text\",\"x\":0.5,\"y\":0.3,\"w\":12.3,\"h\":0.3,\"text\":\"INVENTORY • APPLY THE TRIGGER AND SIZE THE ORDER\",\"size\":12,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":0.8,\"x2\":12.8,\"y2\":0.8,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":1,\"w\":12.3,\"h\":0.6,\"text\":\"4. ORDER: position is 129 units, below 134\",\"size\":28,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"table\",\"x\":0.5,\"y\":1.9,\"w\":5.5,\"h\":2.5,\"rows\":[[\"Inventory component\",\"Units\"],[\"On-hand\",\"126\"],[\"On-order • add\",\"20\"],[\"Committed • subtract\",\"17\"],[\"Inventory position\",\"126 + 20 − 17 = 129\"]],\"size\":17,\"header_fill\":\"808080\",\"header_color\":\"000000\",\"fill\":\"F2F2F2\",\"color\":\"000000\"},{\"type\":\"text\",\"x\":6.4,\"y\":1.9,\"w\":6.4,\"h\":0.35,\"text\":\"POSITION, TRIGGER AND TARGET • UNITS\",\"size\":14,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"chart\",\"x\":6.4,\"y\":2.4,\"w\":6.4,\"h\":3.4,\"kind\":\"column\",\"categories\":[\"Before new order\",\"After new order\"],\"series\":[{\"name\":\"Inventory position\",\"values\":[129,234]},{\"name\":\"Reorder point\",\"values\":[134,134]},{\"name\":\"Target position\",\"values\":[234,234]}],\"colors\":[\"000000\",\"808080\",\"CCCCCC\"],\"size\":12,\"legend\":true,\"labels\":true},{\"type\":\"rect\",\"x\":0.5,\"y\":4.7,\"w\":5.5,\"h\":1.1,\"fill\":\"E6E6E6\"},{\"type\":\"text\",\"x\":0.7,\"y\":4.85,\"w\":5.1,\"h\":0.75,\"text\":\"129 ≤ 134 → ORDER\\nPosition is 5 units below the trigger.\",\"size\":20,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.5,\"y\":6.05,\"w\":12.3,\"h\":0.45,\"text\":\"Order quantity = target position − inventory position = 234 − 129 = 105 units\",\"size\":22,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.5,\"y\":6.55,\"w\":12.3,\"h\":0.3,\"text\":\"Check: 129 + 105 = 234 units. The new order increases on-order stock; receipt occurs later.\",\"size\":16,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":7,\"x2\":12.8,\"y2\":7,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":7.1,\"w\":11.3,\"h\":0.2,\"text\":\"All data are synthetic. After-order illustration assumes no other inventory changes.\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"text\",\"x\":12.1