AAAAAA\"],\"size\":12,\"legend\":true,\"labels\":true},{\"type\":\"text\",\"x\":0.5,\"y\":6.5,\"w\":12.3,\"h\":0.35,\"text\":\"A higher trigger changes when to order. It does not, by itself, specify how many units to order.\",\"size\":17,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":7,\"x2\":12.8,\"y2\":7,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":7.1,\"w\":11.3,\"h\":0.2,\"text\":\"All data are synthetic. Compare the full inventory position with the trigger.\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"text\",\"x\":12.1,\"y\":7.1,\"w\":0.7,\"h\":0.2,\"text\":\"7 / 8\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"right\"}]},{\"background\":\"FFFFFF\",\"elements\":[{\"type\":\"text\",\"x\":0.5,\"y\":0.3,\"w\":12.3,\"h\":0.3,\"text\":\"CHECKLIST • USE BEFORE INITIATING A REORDER\",\"size\":12,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":0.8,\"x2\":12.8,\"y2\":0.8,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":1,\"w\":12.3,\"h\":0.6,\"text\":\"8. Verify the inputs; check the trigger\",\"size\":30,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"table\",\"x\":0.5,\"y\":1.85,\"w\":12.3,\"h\":2.5,\"rows\":[[\"Check\",\"Before ordering\",\"Example\"],[\"1 • Verify units\",\"Use consistent stock units and lead time in days.\",\"18 units/day × 6 days + 26 units\"],[\"2 • Include existing orders\",\"Add on-order stock to on-hand stock.\",\"126 + 20 = 146 units\"],[\"3 • Subtract commitments\",\"Deduct stock already committed.\",\"146 − 17 = 129 units\"],[\"4 • Check the trigger\",\"ORDER at or below; otherwise WAIT.\",\"129 ≤ 134 → ORDER\"]],\"size\":16,\"header_fill\":\"808080\",\"header_color\":\"000000\",\"fill\":\"F2F2F2\",\"color\":\"000000\"},{\"type\":\"text\",\"x\":0.5,\"y\":4.55,\"w\":12.3,\"h\":0.3,\"text\":\"NUMBER LINE • INVENTORY POSITION IN UNITS • DETAIL FROM 120 TO 150\",\"size\":13,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.7,\"y\":5.05,\"w\":4.7,\"h\":0.35,\"text\":\"ORDER at or below 134\",\"size\":18,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":7.5,\"y\":5.05,\"w\":5.1,\"h\":0.35,\"text\":\"WAIT above 134\",\"size\":18,\"color\":\"000000\",\"bold\":true,\"align\":\"right\"},{\"type\":\"line\",\"x\":1,\"y\":5.75,\"x2\":12,\"y2\":5.75,\"color\":\"000000\",\"width\":2},{\"type\":\"line\",\"x\":1,\"y\":5.65,\"x2\":1,\"y2\":5.85,\"color\":\"000000\",\"width\":1},{\"type\":\"line\",\"x\":12,\"y\":5.65,\"x2\":12,\"y2\":5.85,\"color\":\"000000\",\"width\":1},{\"type\":\"line\",\"x\":4.3,\"y\":5.6,\"x2\":4.3,\"y2\":6.05,\"color\":\"000000\",\"width\":2},{\"type\":\"line\",\"x\":6.133,\"y\":5.35,\"x2\":6.133,\"y2\":5.95,\"color\":\"000000\",\"width\":3},{\"type\":\"line\",\"x\":10.533,\"y\":5.6,\"x2\":10.533,\"y2\":6.05,\"color\":\"000000\",\"width\":2},{\"type\":\"text\",\"x\":0.65,\"y\":5.95,\"w\":0.7,\"h\":0.3,\"text\":\"120\",\"size\":13,\"color\":\"000000\",\"bold\":false,\"align\":\"center\"},{\"type\":\"text\",\"x\":11.65,\"y\":5.95,\"w\":0.7,\"h\":0.3,\"text\":\"150\",\"size\":13,\"color\":\"000000\",\"bold\":false,\"align\":\"center\"},{\"type\":\"text\",\"x\":3,\"y\":6.1,\"w\":2.6,\"h\":0.55,\"text\":\"129 • Example\\n5 below → ORDER\",\"size\":15,\"color\":\"000000\",\"bold\":true,\"align\":\"center\"},{\"type\":\"text\",\"x\":5.3,\"y\":4.95,\"w\":1.7,\"h\":0.4,\"text\":\"134 • Trigger\",\"size\":15,\"color\":\"000000\",\"bold\":true,\"align\":\"center\"},{\"type\":\"text\",\"x\":9.1,\"y\":6.1,\"w\":2.85,\"h\":0.55,\"text\":\"146 • Practice\\n12 above → WAIT\",\"size\":15,\"color\":\"000000\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":0.5,\"y\":7,\"x2\":12.8,\"y2\":7,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":7.1,\"w\":11.3,\"h\":0.2,\"text\":\"All data are synthetic. If ordering, calculate quanti