its.\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"line\",\"x\":7.1,\"y\":5.4,\"x2\":12.1,\"y2\":5.4,\"color\":\"E3CFAE\",\"width\":1.5},{\"type\":\"text\",\"x\":7.1,\"y\":5.55,\"w\":5.0,\"h\":0.6,\"text\":\"My answer: ________   Gap: ____ units\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.9,\"y\":6.7,\"w\":11.53,\"h\":0.45,\"text\":\"The answer is revealed on the next slide.\",\"size\":14,\"color\":\"7A6650\",\"align\":\"center\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.9,\"y\":0.4,\"w\":11.53,\"h\":0.4,\"text\":\"ANSWER & COMMON MISTAKES\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"text\",\"x\":0.9,\"y\":0.75,\"w\":11.53,\"h\":0.8,\"text\":\"Practice Answer, Then Three Traps\",\"size\":34,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"center\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.9,\"y\":1.95,\"w\":11.53,\"h\":1.25,\"fill\":\"7A8450\",\"radius\":true},{\"type\":\"text\",\"x\":1.2,\"y\":2.25,\"w\":3.4,\"h\":0.65,\"text\":\"Answer: WAIT\",\"size\":28,\"color\":\"FFFFFF\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":4.7,\"y\":2.08,\"w\":7.5,\"h\":1.0,\"text\":\"135 units > 123 units. The position is 135 − 123 = 12 units above the trigger, so no order today.\",\"size\":16,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.9,\"y\":3.5,\"w\":3.6,\"h\":3.4,\"fill\":\"F5E6CC\",\"line\":\"E3CFAE\",\"radius\":true},{\"type\":\"text\",\"x\":1.15,\"y\":3.65,\"w\":3.1,\"h\":0.35,\"text\":\"MISTAKE 1\",\"size\":13,\"color\":\"C45B3A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.0,\"w\":3.1,\"h\":0.85,\"text\":\"Comparing on-hand alone with the trigger\",\"size\":17,\"color\":\"4A3B2A\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.95,\"w\":3.1,\"h\":1.8,\"text\":\"Instead, use inven