\":22,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":2.9,\"w\":11.0,\"h\":0.35,\"text\":\"Units: (units/day × days) = units, then add safety stock in units.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.8,\"y\":3.5,\"w\":11.73,\"h\":1.35,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"rect\",\"x\":0.8,\"y\":3.5,\"w\":0.12,\"h\":1.35,\"fill\":\"C45B3A\"},{\"type\":\"text\",\"x\":1.2,\"y\":3.6,\"w\":11.0,\"h\":0.4,\"text\":\"2 · INVENTORY POSITION (what you really have)\",\"size\":14,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":4.0,\"w\":11.0,\"h\":0.5,\"text\":\"Inventory position = on-hand + on-order − committed\",\"size\":22,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":4.45,\"w\":11.0,\"h\":0.35,\"text\":\"Count stock on the shelf, add stock already ordered, subtract stock already promised.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.8,\"y\":5.05,\"w\":11.73,\"h\":1.35,\"fill\":\"C45B3A\",\"radius\":true},{\"type\":\"text\",\"x\":1.2,\"y\":5.15,\"w\":11.0,\"h\":0.4,\"text\":\"3 · THE DECISION\",\"size\":14,\"bold\":true,\"color\":\"FFE9DC\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.2,\"y\":5.55,\"w\":11.0,\"h\":0.6,\"text\":\"If inventory position ≤ reorder point → place an ORDER. Otherwise → WAIT.\",\"size\":22,\"bold\":true,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"text\",\"x\":0.8,\"y\":6.6,\"w\":11.73,\"h\":0.45,\"text\":\"Always compare the inventory position, not on-hand alone, with the reorder point.\",\"size\":14,\"color\":\"7A6650\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"Worked Example: Finding the Reorder Point\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":\"Every step sho