gn\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.8,\"w\":7.0,\"h\":1.3,\"text\":\"Using the rule, should you ORDER or WAIT? Write the comparison and your decision.\",\"size\":20,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":8.8,\"y\":2.05,\"w\":3.73,\"h\":4.15,\"fill\":\"FFFDF6\",\"line\":\"D9C3A0\",\"radius\":true},{\"type\":\"text\",\"x\":9.1,\"y\":2.2,\"w\":3.2,\"h\":0.45,\"text\":\"Your work\",\"size\":19,\"bold\":true,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":9.1,\"y\":2.8,\"w\":3.2,\"h\":0.35,\"text\":\"Comparison\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"text\",\"x\":9.1,\"y\":3.15,\"w\":3.2,\"h\":0.55,\"text\":\"135  ____  123\",\"size\":24,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":9.1,\"y\":4.0,\"w\":3.2,\"h\":0.35,\"text\":\"Decision\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"line\",\"x\":9.1,\"y\":4.85,\"x2\":12.2,\"y2\":4.85,\"color\":\"7A6650\",\"width\":1.5},{\"type\":\"text\",\"x\":9.1,\"y\":5.2,\"w\":3.2,\"h\":0.8,\"text\":\"Answer revealed on the next slide.\",\"size\":13,\"color\":\"C45B3A\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"Answer and Common Misconceptions\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":\"First, the practice answer, then three mistakes to avoid\",\"size\":15,\"align\":\"center\",\"color\":\"7A6650\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.8,\"y\":1.9,\"w\":11.73,\"h\":1.4,\"fill\":\"C45B3A\",\"radius\":true},{\"type\":\"text\",\"x\":1.15,\"y\":2.0,\"w\":11.1,\"h\":0.55,\"text\":\"Practice answer: WAIT\",\"size\":26,\"bold\":true,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":2.6,\"w\":11.1,\"h\":0.6,\"text\":\"135 units > 123 units. The position is 12 units above the trigger (135 − 123 = 12), so no order yet.\",\"size\":17,\"color\":\"FFFFFF\",\"align\":\"left\"},{\"type\":\"columns\",\"x\":0.8,\"y\":3.6,\"w\":11.73,\"h\":3.0,\"fill\":\"F5E6C8\",\"color\":\"4A3B2A\",\"items\":[{\"title\":\"On-hand alone\",\"body\":\"Do not compare on-hand alone with the trigger. Use on-hand + on-order − committed.\"},{\"title\":\"Safety stock × lead time\",\"body\":\"Do not multiply safety stock by lead time. Only daily demand is multiplied; safety stock is added once.\"},{\"title\":\"Trigger ≠ quantity\",\"body\":\"A larger reorder point is a trigger, not the order quantity. It tells you when, not how much.\"}]},{\"type\":\"text\",\"x\":0.8,\"y\":6.75,\"w\":11.73,\"h\":0.4,\"text\":\"Each of these mistakes can flip the ORDER / WAIT decision. Check them every time.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"}]},{\"background\":\"FFF8E7\",\"elements\":[{\"type\":\"text\",\"x\":0.8,\"y\":0.35,\"w\":11.73,\"h\":0.7,\"text\":\"Pre-Order Checklist\",\"size\":30,\"bold\":true,\"align\":\"center\",\"color\":\"4A3B2A\"},{\"type\":\"text\",\"x\":0.8,\"y\":1.05,\"w\":11.73,\"h\":0.45,\"text\":\"Four checks before you place any order\",\"size\":15,\"align\":\"center\",\"color\":\"7A6650\"},{\"type\":\"line\",\"x\":6.17,\"y\":1.6,\"x2\":7.17,\"y2\":1.6,\"color\":\"C45B3A\",\"width\":2.5},{\"type\":\"rect\",\"x\":0.8,\"y\":1.85,\"w\":5.7,\"h\":4.4,\"fill\":\"F5E6C8\",\"radius\":true},{\"type\":\"rect\",\"x\":0.8,\"y\":1.85,\"w\":0.12,\"h\":4.4,\"fill\":\"C45B3A\"},{\"type\":\"text\",\"x\":1.15,\"y\":2.05,\"w\":5.15,\"h\":0.9,\"text\":\"1 · Verify units: every number uses the same unit of measure.\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":3.05,\"w\":5.15,\"h\":0.9,\"text\":\"2 · Include existing orders: add the on-order quantity.\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":4.05,\"w\":5.15,\"h\":0.9,\"text\":\"3 · Subtract commitments: remove units already promised.\",\"size\":16,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.15,\"y\":5.05,\"w\":5.15,\"h\":0.9,\"text\":\"4 · Then check the trigger: ORDER only if position ≤ reorder point.\",\"size\":16,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.8,\"y\":1.85,\"w\":5.73,\"h\":4.4,\"fill\":\"FFFDF6\",\"line\":\"E3CFA9\",\"radius\":true},{\"type\":\"text\",\"x\":7.0,\"y\":2.0,\"w\":5.4,\"h\":0.4,\"text\":\"Where does the position sit?\",\"size\":16,\"bold\":true,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":7.0,\"y\":2.4,\"w\":5.4,\"h\":0.6,\"text\":\"At or left of the trigger: ORDER. Right of it: WAIT.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":7.0,\"y\":3.95,\"w\":2.34,\"h\":0.55,\"fill\":\"F2D3C5\"},{\"type\":\"rect\",\"x\":9.34,\"y\":3.95,\"w\":3.06,\"h\":0.55,\"fill\":\"E4E6CF\"},{\"type\":\"text\",\"x\":7.0,\"y\":4.02,\"w\":2.34,\"h\":0.4,\"text\":\"ORDER zone (≤ 123)\",\"size\":12,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"center\"},{\"type\":\"text\",\"x\":9.34,\"y\":4.02,\"w\":3.06,\"h\":0.4,\"text\":\"WAIT zone (> 123)\",\"size\":12,\"bold\":true,\"color\":\"5E6B3A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":7.0,\"y\":4.5,\"x2\":12.4,\"y2\":4.5,\"color\":\"4A3B2A\",\"width\":2},{\"type\":\"line\",\"x\":9.34,\"y\":3.55,\"x2\":9.34,\"y2\":4.85,\"color\":\"C45B3A\",\"width\":3},{\"type\":\"text\",\"x\":8.24,\"y\":3.15,\"w\":2.2,\"h\":0.4,\"text\":\"Reorder point 123\",\"size\":13,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":8.44,\"y\":4.5,\"x2\":8.44,\"y2\":4.75,\"color\":\"4A3B2A\",\"width\":2},{\"type\":\"text\",\"x\":7.48,\"y\":4.8,\"w\":1.8,\"h\":0.7,\"text\":\"118\\nexample: ORDER\",\"size\":12,\"color\":\"4A3B2A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":11.5,\"y\":4.5,\"x2\":11.5,\"y2\":4.75,\"color\":\"4A3B2A\",\"width\":2},{\"