{"type":"item.completed","item":{"id":"item_1","type":"agent_message","text":"{\"theme\":{\"background\":\"FFFFFF\",\"ink\":\"000000\",\"accent\":\"808080\",\"font\":\"Arial\"},\"slides\":[{\"background\":\"FFFFFF\",\"elements\":[{\"type\":\"text\",\"x\":0.5,\"y\":0.3,\"w\":12.3,\"h\":0.3,\"text\":\"INVENTORY REORDER PROTOCOL • JUNIOR STOCKROOM COORDINATORS\",\"size\":12,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":0.8,\"x2\":12.8,\"y2\":0.8,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":1,\"w\":12.3,\"h\":0.6,\"text\":\"1. Learning goal\",\"size\":30,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.5,\"y\":1.9,\"w\":12.3,\"h\":1.1,\"fill\":\"E6E6E6\"},{\"type\":\"text\",\"x\":0.7,\"y\":2.05,\"w\":11.9,\"h\":0.8,\"text\":\"Use a simple reorder-point rule to decide when to initiate a restocking order.\",\"size\":24,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"text\",\"x\":0.5,\"y\":3.25,\"w\":12.3,\"h\":0.4,\"text\":\"By the end, you should be able to complete these steps.\",\"size\":18,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"table\",\"x\":0.5,\"y\":3.85,\"w\":12.3,\"h\":2.4,\"rows\":[[\"Step\",\"Skill\",\"Evidence of understanding\"],[\"01 • Understand\",\"Explain the trigger and inventory position\",\"Identify the quantities in each formula\"],[\"02 • Apply\",\"Work through a complete reorder example\",\"Show arithmetic, units and the order decision\"],[\"03 • Check\",\"Complete a short practice exercise\",\"Choose ORDER or WAIT and explain why\"]],\"size\":17,\"header_fill\":\"808080\",\"header_color\":\"000000\",\"fill\":\"F2F2F2\",\"color\":\"000000\"},{\"type\":\"text\",\"x\":0.5,\"y\":6.45,\"w\":12.3,\"h\":0.4,\"text\":\"Rule → worked example → inventory decision → process → practice → answer → checklist\",\"size\":16,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":7,\"x2\":12.8,\"y2\":7,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":7.1,\"w\":11.3,\"h\":0.25,\"text\":\"All data are synthetic. Stock quantities are expressed in units.\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"left\"},{\"type\":\"text\",\"x\":12.1,\"y\":7.1,\"w\":0.7,\"h\":0.25,\"text\":\"1 / 8\",\"size\":10,\"color\":\"000000\",\"bold\":false,\"align\":\"right\"}]},{\"background\":\"FFFFFF\",\"elements\":[{\"type\":\"text\",\"x\":0.5,\"y\":0.3,\"w\":12.3,\"h\":0.3,\"text\":\"RULE • TWO CALCULATIONS, ONE DECISION\",\"size\":12,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"line\",\"x\":0.5,\"y\":0.8,\"x2\":12.8,\"y2\":0.8,\"color\":\"808080\",\"width\":1},{\"type\":\"text\",\"x\":0.5,\"y\":1,\"w\":12.3,\"h\":0.6,\"text\":\"2. Calculate the trigger; compare the position\",\"size\":28,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.5,\"y\":1.85,\"w\":12.3,\"h\":0.85,\"fill\":\"E6E6E6\"},{\"type\":\"text\",\"x\":0.7,\"y\":2,\"w\":11.9,\"h\":0.55,\"text\":\"Reorder point = daily demand × lead time in days + safety stock\",\"size\":23,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"rect\",\"x\":0.5,\"y\":2.9,\"w\":12.3,\"h\":0.85,\"fill\":\"F2F2F2\"},{\"type\":\"text\",\"x\":0.7,\"y\":3.05,\"w\":11.9,\"h\":0.55,\"text\":\"Inventory position = on-hand + on-order − committed\",\"size\":23,\"color\":\"000000\",\"bold\":true,\"align\":\"left\"},{\"type\":\"table\",\"x\":0.5,\"y\":4,\"w\":12.3,\"h\":1.8,\"rows\":[[\"Quantity\",\"Meaning\",\"Unit check\"],[\"Reorder point\",\"Lead-time demand + safety buffer\",\"(units/day × days) + units = units\"],[\"Inventory position\",\"Stock after orders and commitments\",\"units + units − units = units\"]],\"size\":17,\"header_fill\":\"808080\",\"header_color\":\"000000\",\"fill\":\"F2F2F2\",\"color\":\"000000\"},{\"type\":\"text\",\"x\":0.5,\"y\":6,\"w\":12.3,\"h\":0.55,\"text\":\"ORDER when inventory position ≤ reorder poin