lor\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":1.05,\"y\":5.05,\"w\":5.25,\"h\":0.95,\"text\":\"4.  Then check the trigger: ORDER only if position ≤ reorder point.\",\"size\":16,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":6.8,\"y\":1.85,\"w\":5.73,\"h\":4.4,\"fill\":\"FFFDF6\",\"line\":\"E3CFA9\",\"radius\":true},{\"type\":\"text\",\"x\":7.0,\"y\":2.0,\"w\":5.4,\"h\":0.4,\"text\":\"Where does the position sit?\",\"size\":16,\"bold\":true,\"color\":\"4A3B2A\",\"align\":\"left\"},{\"type\":\"text\",\"x\":7.0,\"y\":2.4,\"w\":5.4,\"h\":0.6,\"text\":\"At or left of the trigger: ORDER. Right of it: WAIT.\",\"size\":13,\"color\":\"7A6650\",\"align\":\"left\"},{\"type\":\"rect\",\"x\":7.0,\"y\":3.95,\"w\":2.34,\"h\":0.55,\"fill\":\"F2D3C5\"},{\"type\":\"rect\",\"x\":9.34,\"y\":3.95,\"w\":3.06,\"h\":0.55,\"fill\":\"E4E6CF\"},{\"type\":\"text\",\"x\":7.0,\"y\":4.02,\"w\":2.34,\"h\":0.4,\"text\":\"ORDER zone (≤ 123)\",\"size\":12,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"center\"},{\"type\":\"text\",\"x\":9.34,\"y\":4.02,\"w\":3.06,\"h\":0.4,\"text\":\"WAIT zone (> 123)\",\"size\":12,\"bold\":true,\"color\":\"5E6B3A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":7.0,\"y\":4.5,\"x2\":12.4,\"y2\":4.5,\"color\":\"4A3B2A\",\"width\":2},{\"type\":\"line\",\"x\":9.34,\"y\":3.55,\"x2\":9.34,\"y2\":4.85,\"color\":\"C45B3A\",\"width\":3},{\"type\":\"text\",\"x\":8.24,\"y\":3.15,\"w\":2.2,\"h\":0.4,\"text\":\"Reorder point 123\",\"size\":13,\"bold\":true,\"color\":\"C45B3A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":8.44,\"y\":4.5,\"x2\":8.44,\"y2\":4.75,\"color\":\"4A3B2A\",\"width\":2},{\"type\":\"text\",\"x\":7.48,\"y\":4.95,\"w\":1.92,\"h\":0.7,\"text\":\"118\\nexample: ORDER\",\"size\":12,\"color\":\"4A3B2A\",\"align\":\"center\"},{\"type\":\"line\",\"x\":11.5,\"y\":4.5,\"x2\":11.5,\"y2\":4.75,\"color\":\"4A3B2A\",\"width\":2},{\"type\":\"text\",\"x\":10.7,\"y\":4.95,\"w\":1.6,\"h\":0.7,\"text\":\"135\\npractice: WAIT\"